phase3.solution:
class GameCharacter:
    def __init__(self, name, level):
        self.name = name
        self.level = level

    def attack(self):
        return self.level * 10

    def defend(self):
        return self.level * 2

    def display(self):
        return f"{self.name}: Level {self.level}, Attack {self.attack()}, Defense {self.defend()}"

class Fighter(GameCharacter):
    def __init__(self, name, level):
        super().__init__(name, level)
        self.class_name = "Fighter"

    def attack(self):
        return self.level * 12

    def defend(self):
        return self.level * 3

    def display(self):
        return f"{self.name} ({self.class_name}): {super().display()}"

class Rogue(GameCharacter):
    def __init__(self, name, level):
        super().__init__(name, level)
        self.class_name = "Rogue"

    def attack(self):
        import random
        base = self.level * 15
        if random.random() < 0.3:  # 30% critical
            return base * 2
        return base

    def defend(self):
        return self.level * 2

    def display(self):
        return f"{self.name} ({self.class_name}): {super().display()} (critical chance: 30%)"

class Healer(GameCharacter):
    def __init__(self, name, level):
        super().__init__(name, level)
        self.class_name = "Healer"

    def attack(self):
        return self.level * 5

    def defend(self):
        return self.level * 4

    def heal(self, target):
        amount = self.level * 5
        print(f"{self.name} heals {target.name} for {amount} HP!")

    def display(self):
        return f"{self.name} ({self.class_name}): {super().display()}"

# Create characters
aragorn = Fighter("Aragorn", 15)
legolas = Rogue("Legolas", 18)
gandalf = Healer("Gandalf", 20)

print(aragorn.display())
print(legolas.display())
print(gandalf.display())
